ock;//define a object of DS1307 class\nvoid setup()\n{\n    Serial.begin(9600);\n    clock.begin();\n    clock.fillByYMD(2013,1,19);//Jan 19,2013\n    clock.fillByHMS(15,28,30);//15:28 30"\n    clock.fillDayOfWeek(SAT);//Saturday\n    clock.setTime();//write time to the RTC chip\n}\nvoid loop()\n{\n    printTime();\n}\n    /*Function: Display time on the serial monitor*/\nvoid printTime()\n{\n    clock.getTime();\n    Serial.print(clock.hour, DEC);\n    Serial.print(":");\n    Serial.print(clock.minute, DEC);\n    Serial.print(":");\n    Serial.print(clock.second, DEC);\n    Serial.print("  ");\n    Serial.print(clock.month, DEC);\n    Serial.print("/");\n    Serial.print(clock.dayOfMonth, DEC);\n    Serial.print("/");\n    Serial.print(clock.year+2000, DEC);\n    Serial.print(" ");\n    Serial.print(clock.dayOfMonth);\n    Serial.print("*");\n    switch (clock.dayOfWeek)// Friendly printout the weekday\n    {\n        case MON:\n        Serial.print("MON");\n        break;\n        case TUE:\n        Serial.print("TUE");\n        break;\n        case WED:\n        Serial.print("WED");\n        break;\n        case THU:\n        Serial.print("THU");\n        break;\n        case FRI:\n        Serial.print("FRI");\n        break;\n        case SAT:\n        Serial.print("SAT");\n        break;\n        case SUN:\n        Serial.print("SUN");\n        break;\n    }\n    Serial.println(" ");\n}\n'})}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Paso 4."})," Configura la hora. Cambia los argumentos de la funci\xf3n a la fecha/hora actual. Por favor, presta atenci\xf3n al formato de los argumentos."]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-c",children:'clock.fillByYMD(2013,1,19);//Jan 19,2013\nclock.fillByHMS(15,28,30);//15:28 30"\nclock.fillDayOfWeek(SAT);//Saturday\n'})}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Paso 5."})," Sube el c\xf3digo y abre el monitor serie para recibir los datos del sensor"]}